const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let filter='Todos';const query=document.querySelector('#search');
function render(){const q=query.value.trim().toLocaleLowerCase('es');const found=projects.filter(p=>(filter==='Todos'||p.category===filter)&&[p.title,p.text,p.type,...p.tags].join(' ').toLocaleLowerCase('es').includes(q));document.querySelector('#cards').innerHTML=found.map(p=>`<article class="card"><span class="resource-number">${String(projects.indexOf(p)+1).padStart(2,'0')}</span><span class="micro">${esc(p.type)}</span><h3>${esc(p.title)}</h3><p>${esc(p.text)}</p><div class="tags">${p.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div><div class="card-links">${p.links.map(([name,url])=>`<a href="${url}">${esc(name)} ↗</a>`).join('')}</div></article>`).join('');document.querySelector('#count').textContent=`${found.length} recursos · ${filter}`;document.querySelector('#empty').hidden=found.length>0;}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});render();}));query.addEventListener('input',render);render();
document.querySelector('#events').innerHTML=events.map(e=>`<article class="event"><div class="event-date">${e.date}<br><span class="status ${e.upcoming?'upcoming':''}">${esc(e.status)}</span></div><div><h3>${esc(e.name)}</h3><p>${esc(e.topic)}</p><div class="tags">${e.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div></div>${e.url?`<a href="${e.url}">${esc(e.label)}</a>`:'<span></span>'}</article>`).join('');
